     1→package lexer
     2→
     3→import (
     4→	"fmt"
     5→	"unicode"
     6→)
     7→
     8→// Lexer - Julia 렉서
     9→type Lexer struct {
    10→	input  string
    11→	pos    int  // 현재 위치
    12→	line   int  // 현재 줄
    13→	column int  // 현재 열
    14→	offset int  // 바이트 오프셋
    15→	ch     rune // 현재 문자
    16→	file   string
    17→}
    18→
    19→// NewLexer - 새로운 Lexer 생성
    20→func NewLexer(input string) *Lexer {
    21→	l := &Lexer{
    22→		input:  input,
    23→		pos:    0,
    24→		line:   1,
    25→		column: 0,
    26→		offset: 0,
    27→		ch:     rune(0),
    28→		file:   "<stdin>",
    29→	}
    30→	l.readChar()
    31→	return l
    32→}
    33→
    34→// NewLexerWithFile - 파일명을 포함한 Lexer 생성
    35→func NewLexerWithFile(input, filename string) *Lexer {
    36→	l := NewLexer(input)
    37→	l.file = filename
    38→	return l
    39→}
    40→
    41→// readChar - 다음 문자 읽기
    42→func (l *Lexer) readChar() {
    43→	if l.pos >= len(l.input) {
    44→		l.ch = rune(0)
    45→	} else {
    46→		l.ch = rune(l.input[l.pos])
    47→	}
    48→	l.pos++
    49→	l.offset++
    50→	l.column++
    51→}
    52→
    53→// peekChar - 다음 문자 미리보기 (읽지 않음)
    54→func (l *Lexer) peekChar() rune {
    55→	if l.pos >= len(l.input) {
    56→		return rune(0)
    57→	}
    58→	return rune(l.input[l.pos])
    59→}
    60→
    61→// peekCharN - n번째 앞의 문자 보기
    62→func (l *Lexer) peekCharN(n int) rune {
    63→	pos := l.pos - 1 + n
    64→	if pos >= len(l.input) || pos < 0 {
    65→		return rune(0)
    66→	}
    67→	return rune(l.input[pos])
    68→}
    69→
    70→// skipWhitespace - 공백과 탭 건너뛰기 (줄바꿈 제외)
    71→func (l *Lexer) skipWhitespace() {
    72→	for l.ch == ' ' || l.ch == '\t' || l.ch == '\r' {
    73→		l.readChar()
    74→	}
    75→}
    76→
    77→// skipLineComment - 줄 주석 건너뛰기 (#...)
    78→func (l *Lexer) skipLineComment() {
    79→	for l.ch != '\n' && l.ch != rune(0) {
    80→		l.readChar()
    81→	}
    82→}
    83→
    84→// skipBlockComment - 블록 주석 건너뛰기 (#=...=#)
    85→func (l *Lexer) skipBlockComment() bool {
    86→	if l.ch != '#' {
    87→		return false
    88→	}
    89→	if l.peekChar() != '=' {
    90→		return false
    91→	}
    92→	
    93→	l.readChar() // '#'
    94→	l.readChar() // '='
    95→	
    96→	depth := 1
    97→	for depth > 0 && l.ch != rune(0) {
    98→		if l.ch == '#' && l.peekChar() == '=' {
    99→			l.readChar() // '#'
   100→			l.readChar() // '='
   101→			depth++
   102→		} else if l.ch == '=' && l.peekChar() == '#' {
   103→			l.readChar() // '='
   104→			l.readChar() // '#'
   105→			depth--
   106→		} else {
   107→			if l.ch == '\n' {
   108→				l.line++
   109→				l.column = 0
   110→			}
   111→			l.readChar()
   112→		}
   113→	}
   114→	return true
   115→}
   116→
   117→// NextToken - 다음 토큰 반환
   118→func (l *Lexer) NextToken() Token {
   119→	l.skipWhitespace()
   120→	
   121→	// 주석 처리
   122→	for {
   123→		if l.ch == '#' {
   124→			if l.peekChar() == '=' {
   125→				if l.skipBlockComment() {
   126→					l.skipWhitespace()
   127→					continue
   128→				}
   129→			} else {
   130→				l.skipLineComment()
   131→				l.skipWhitespace()
   132→				continue
   133→			}
   134→		}
   135→		break
   136→	}
   137→
   138→	line := l.line
   139→	column := l.column
   140→
   141→	// EOF
   142→	if l.ch == rune(0) {
   143→		return l.makeToken(TokenEOF, "", line, column)
   144→	}
   145→
   146→	// 개행
   147→	if l.ch == '\n' {
   148→		l.readChar()
   149→		l.line++
   150→		l.column = 0
   151→		return l.makeToken(TokenNewline, "\n", line, column)
   152→	}
   153→
   154→	// 문자열
   155→	if l.ch == '"' || l.ch == '\'' {
   156→		return l.readString(line, column)
   157→	}
   158→
   159→	// 숫자
   160→	if unicode.IsDigit(l.ch) {
   161→		return l.readNumber(line, column)
   162→	}
   163→
   164→	// 심볼 (:name)
   165→	if l.ch == ':' && unicode.IsLetter(l.peekChar()) {
   166→		return l.readSymbol(line, column)
   167→	}
   168→
   169→	// 식별자 또는 키워드 또는 매크로
   170→	if unicode.IsLetter(l.ch) || l.ch == '_' {
   171→		return l.readIdentifierOrKeyword(line, column)
   172→	}
   173→
   174→	// 연산자 및 기타
   175→	return l.readOperatorOrDelimiter(line, column)
   176→}
   177→
   178→// readString - 문자열 읽기
   179→func (l *Lexer) readString(line, column int) Token {
   180→	quote := l.ch
   181→	l.readChar()
   182→	start := l.pos - 1
   183→
   184→	for l.ch != quote && l.ch != rune(0) {
   185→		if l.ch == '\\' {
   186→			l.readChar() // escape 문자
   187→		}
   188→		if l.ch == '\n' {
   189→			l.line++
   190→			l.column = 0
   191→		}
   192→		l.readChar()
   193→	}
   194→
   195→	end := l.pos
   196→	if end > len(l.input) {
   197→		end = len(l.input)
   198→	}
   199→	
   200→	lexeme := l.input[start:end]
   201→	if l.ch == quote {
   202→		l.readChar()
   203→	}
   204→
   205→	return l.makeToken(TokenString, lexeme, line, column)
   206→}
   207→
   208→// readNumber - 숫자 읽기 (정수, 부동소수, 지수, 복소수, 유리수)
   209→func (l *Lexer) readNumber(line, column int) Token {
   210→	start := l.pos - 1
   211→	if start < 0 {
   212→		start = 0
   213→	}
   214→
   215→	isFloat := false
   216→	isComplex := false
   217→	isRational := false
   218→
   219→	// 정수 부분
   220→	for unicode.IsDigit(l.ch) {
   221→		l.readChar()
   222→	}
   223→
   224→	// 부동소수점
   225→	if l.ch == '.' && unicode.IsDigit(l.peekChar()) {
   226→		isFloat = true
   227→		l.readChar()
   228→		for unicode.IsDigit(l.ch) {
   229→			l.readChar()
   230→		}
   231→	}
   232→
   233→	// 지수 표기법
   234→	if (l.ch == 'e' || l.ch == 'E') && (unicode.IsDigit(l.peekChar()) || l.peekChar() == '+' || l.peekChar() == '-') {
   235→		isFloat = true
   236→		l.readChar()
   237→		if l.ch == '+' || l.ch == '-' {
   238→			l.readChar()
   239→		}
   240→		for unicode.IsDigit(l.ch) {
   241→			l.readChar()
   242→		}
   243→	}
   244→
   245→	// 복소수 (e.g., 1im, 2.5e-10im)
   246→	if l.ch == 'i' && l.peekChar() == 'm' {
   247→		isComplex = true
   248→		l.readChar()
   249→		l.readChar()
   250→	}
   251→
   252→	// 유리수 (e.g., 1//2)
   253→	if l.ch == '/' && l.peekChar() == '/' {
   254→		isRational = true
   255→		l.readChar()
   256→		l.readChar()
   257→		for unicode.IsDigit(l.ch) {
   258→			l.readChar()
   259→		}
   260→	}
   261→
   262→	end := l.pos
   263→	if end > len(l.input) {
   264→		end = len(l.input)
   265→	}
   266→	lexeme := l.input[start:end]
   267→
   268→	tokenType := TokenInteger
   269→	if isFloat {
   270→		tokenType = TokenFloat
   271→	}
   272→	if isComplex {
   273→		tokenType = TokenComplexNumber
   274→	}
   275→	if isRational {
   276→		tokenType = TokenRationalNumber
   277→	}
   278→
   279→	return l.makeToken(tokenType, lexeme, line, column)
   280→}
   281→
   282→// readSymbol - 심볼 읽기 (:name)
   283→func (l *Lexer) readSymbol(line, column int) Token {
   284→	l.readChar() // ':'
   285→	start := l.pos
   286→
   287→	for unicode.IsLetter(l.ch) || unicode.IsDigit(l.ch) || l.ch == '_' {
   288→		l.readChar()
   289→	}
   290→
   291→	end := l.pos
   292→	if end > len(l.input) {
   293→		end = len(l.input)
   294→	}
   295→	lexeme := ":" + l.input[start:end]
   296→
   297→	return l.makeToken(TokenSymbol, lexeme, line, column)
   298→}
   299→
   300→// readIdentifierOrKeyword - 식별자 또는 키워드 읽기
   301→func (l *Lexer) readIdentifierOrKeyword(line, column int) Token {
   302→	start := l.pos - 1
   303→	if start < 0 {
   304→		start = 0
   305→	}
   306→
   307→	for unicode.IsLetter(l.ch) || unicode.IsDigit(l.ch) || l.ch == '_' || l.ch == '!' || l.ch == '?' {
   308→		l.readChar()
   309→	}
   310→
   311→	// 현재 위치 - 1이 끝 위치 (readChar()로 한 칸 넘어갔으므로)
   312→	end := l.pos - 1
   313→	if end > len(l.input) {
   314→		end = len(l.input)
   315→	}
   316→	if end < start {
   317→		end = start
   318→	}
   319→	lexeme := l.input[start:end]
   320→
   321→	// 매크로 확인
   322→	if l.ch == '(' || l.ch == '[' || l.ch == '{' {
   323→		// 잠시 보류
   324→	}
   325→
   326→	// 키워드 확인
   327→	if tokenType, ok := Keywords[lexeme]; ok {
   328→		return l.makeToken(tokenType, lexeme, line, column)
   329→	}
   330→
   331→	return l.makeToken(TokenIdentifier, lexeme, line, column)
   332→}
   333→
   334→// readOperatorOrDelimiter - 연산자 또는 구분자 읽기
   335→func (l *Lexer) readOperatorOrDelimiter(line, column int) Token {
   336→	ch := l.ch
   337→	next := l.peekChar()
   338→
   339→	switch ch {
   340→	case '+':
   341→		l.readChar()
   342→		if next == '=' {
   343→			l.readChar()
   344→			return l.makeToken(TokenPlusAssign, "+=", line, column)
   345→		} else if next == '+' {
   346→			l.readChar()
   347→			return l.makeToken(TokenPlusPlus, "++", line, column)
   348→		}
   349→		return l.makeToken(TokenPlus, "+", line, column)
   350→
   351→	case '-':
   352→		l.readChar()
   353→		if next == '>' {
   354→			l.readChar()
   355→			return l.makeToken(TokenArrow, "->", line, column)
   356→		} else if next == '=' {
   357→			l.readChar()
   358→			return l.makeToken(TokenMinusAssign, "-=", line, column)
   359→		} else if next == '-' {
   360→			l.readChar()
   361→			return l.makeToken(TokenMinusMinus, "--", line, column)
   362→		}
   363→		return l.makeToken(TokenMinus, "-", line, column)
   364→
   365→	case '*':
   366→		l.readChar()
   367→		if next == '=' {
   368→			l.readChar()
   369→			return l.makeToken(TokenStarAssign, "*=", line, column)
   370→		}
   371→		return l.makeToken(TokenStar, "*", line, column)
   372→
   373→	case '/':
   374→		l.readChar()
   375→		if next == '/' {
   376→			l.readChar()
   377→			return l.makeToken(TokenTripleDot, "//", line, column)
   378→		} else if next == '=' {
   379→			l.readChar()
   380→			return l.makeToken(TokenSlashAssign, "/=", line, column)
   381→		}
   382→		return l.makeToken(TokenSlash, "/", line, column)
   383→
   384→	case '%':
   385→		l.readChar()
   386→		if next == '=' {
   387→			l.readChar()
   388→			return l.makeToken(TokenPercentAssign, "%=", line, column)
   389→		}
   390→		return l.makeToken(TokenPercent, "%", line, column)
   391→
   392→	case '^':
   393→		l.readChar()
   394→		if next == '=' {
   395→			l.readChar()
   396→			return l.makeToken(TokenCaretAssign, "^=", line, column)
   397→		}
   398→		return l.makeToken(TokenCaret, "^", line, column)
   399→
   400→	case '=':
   401→		l.readChar()
   402→		if next == '=' {
   403→			l.readChar()
   404→			return l.makeToken(TokenEqualEqual, "==", line, column)
   405→		} else if next == '>' {
   406→			l.readChar()
   407→			return l.makeToken(TokenFatArrow, "=>", line, column)
   408→		}
   409→		return l.makeToken(TokenEqual, "=", line, column)
   410→
   411→	case '!':
   412→		l.readChar()
   413→		if next == '=' {
   414→			l.readChar()
   415→			return l.makeToken(TokenNotEqual, "!=", line, column)
   416→		}
   417→		return l.makeToken(TokenNot, "!", line, column)
   418→
   419→	case '<':
   420→		l.readChar()
   421→		if next == '=' {
   422→			l.readChar()
   423→			return l.makeToken(TokenLessEqual, "<=", line, column)
   424→		} else if next == '<' {
   425→			l.readChar()
   426→			if l.ch == '=' {
   427→				l.readChar()
   428→				return l.makeToken(TokenLeftShiftAssign, "<<=", line, column)
   429→			}
   430→			return l.makeToken(TokenLeftShift, "<<", line, column)
   431→		} else if next == '|' {
   432→			l.readChar()
   433→			return l.makeToken(TokenCompArrow, "<|", line, column)
   434→		}
   435→		return l.makeToken(TokenLess, "<", line, column)
   436→
   437→	case '>':
   438→		l.readChar()
   439→		if next == '=' {
   440→			l.readChar()
   441→			return l.makeToken(TokenGreaterEqual, ">=", line, column)
   442→		} else if next == '>' {
   443→			l.readChar()
   444→			if l.ch == '>' {
   445→				l.readChar()
   446→				if l.ch == '=' {
   447→					l.readChar()
   448→					return l.makeToken(TokenUnsignedRightShiftAssign, ">>>=", line, column)
   449→				}
   450→				return l.makeToken(TokenUnsignedRightShift, ">>>", line, column)
   451→			} else if l.ch == '=' {
   452→				l.readChar()
   453→				return l.makeToken(TokenRightShiftAssign, ">>=", line, column)
   454→			}
   455→			return l.makeToken(TokenRightShift, ">>", line, column)
   456→		}
   457→		return l.makeToken(TokenGreater, ">", line, column)
   458→
   459→	case '&':
   460→		l.readChar()
   461→		if next == '&' {
   462→			l.readChar()
   463→			if l.ch == '=' {
   464→				l.readChar()
   465→				return l.makeToken(TokenLogicalAndAssign, "&&=", line, column)
   466→			}
   467→			return l.makeToken(TokenAnd, "&&", line, column)
   468→		} else if next == '=' {
   469→			l.readChar()
   470→			return l.makeToken(TokenAndAssign, "&=", line, column)
   471→		}
   472→		return l.makeToken(TokenAmpersand, "&", line, column)
   473→
   474→	case '|':
   475→		l.readChar()
   476→		if next == '|' {
   477→			l.readChar()
   478→			if l.ch == '=' {
   479→				l.readChar()
   480→				return l.makeToken(TokenLogicalOrAssign, "||=", line, column)
   481→			}
   482→			return l.makeToken(TokenOr, "||", line, column)
   483→		} else if next == '>' {
   484→			l.readChar()
   485→			return l.makeToken(TokenPipeArrow, "|>", line, column)
   486→		} else if next == '=' {
   487→			l.readChar()
   488→			return l.makeToken(TokenPipeAssign, "|=", line, column)
   489→		}
   490→		return l.makeToken(TokenPipe, "|", line, column)
   491→
   492→	case '.':
   493→		l.readChar()
   494→		if next == '.' {
   495→			l.readChar()
   496→			if l.ch == '.' {
   497→				l.readChar()
   498→				return l.makeToken(TokenTripleDot, "...", line, column)
   499→			}
   500→			return l.makeToken(TokenDoubleDot, "..", line, column)
   501→		} else if next == ',' {
   502→			l.readChar()
   503→			return l.makeToken(TokenComma_Dot, ",.", line, column)
   504→		}
   505→		return l.makeToken(TokenDot, ".", line, column)
   506→
   507→	case ':':
   508→		l.readChar()
   509→		if next == ':' {
   510→			l.readChar()
   511→			return l.makeToken(TokenDoubleColon, "::", line, column)
   512→		}
   513→		return l.makeToken(TokenColon, ":", line, column)
   514→
   515→	case '(':
   516→		l.readChar()
   517→		return l.makeToken(TokenLparen, "(", line, column)
   518→	case ')':
   519→		l.readChar()
   520→		return l.makeToken(TokenRparen, ")", line, column)
   521→	case '{':
   522→		l.readChar()
   523→		return l.makeToken(TokenLbrace, "{", line, column)
   524→	case '}':
   525→		l.readChar()
   526→		return l.makeToken(TokenRbrace, "}", line, column)
   527→	case '[':
   528→		l.readChar()
   529→		return l.makeToken(TokenLbracket, "[", line, column)
   530→	case ']':
   531→		l.readChar()
   532→		return l.makeToken(TokenRbracket, "]", line, column)
   533→	case ',':
   534→		l.readChar()
   535→		return l.makeToken(TokenComma, ",", line, column)
   536→	case ';':
   537→		l.readChar()
   538→		return l.makeToken(TokenSemicolon, ";", line, column)
   539→	case '~':
   540→		l.readChar()
   541→		return l.makeToken(TokenTilde, "~", line, column)
   542→	case '$':
   543→		l.readChar()
   544→		return l.makeToken(TokenDollar, "$", line, column)
   545→	case '@':
   546→		l.readChar()
   547→		return l.makeToken(TokenAt, "@", line, column)
   548→	case '?':
   549→		l.readChar()
   550→		return l.makeToken(TokenQuestionMark, "?", line, column)
   551→
   552→	default:
   553→		l.readChar()
   554→		errMsg := fmt.Sprintf("예상치 못한 문자: %c (U+%04X)", ch, ch)
   555→		return l.makeErrorToken(errMsg, line, column)
   556→	}
   557→}
   558→
   559→// makeToken - 토큰 생성 헬퍼
   560→func (l *Lexer) makeToken(tokenType TokenType, lexeme string, line, column int) Token {
   561→	return Token{
   562→		Type:   tokenType,
   563→		Lexeme: lexeme,
   564→		Pos: Position{
   565→			File:   l.file,
   566→			Line:   line,
   567→			Column: column,
   568→			Offset: l.offset - len(lexeme),
   569→		},
   570→	}
   571→}
   572→
   573→// makeErrorToken - 에러 토큰 생성
   574→func (l *Lexer) makeErrorToken(msg string, line, column int) Token {
   575→	return Token{
   576→		Type:   TokenError,
   577→		Lexeme: msg,
   578→		Pos: Position{
   579→			File:   l.file,
   580→			Line:   line,
   581→			Column: column,
   582→			Offset: l.offset,
   583→		},
   584→	}
   585→}
   586→
   587→// ScanAll - 모든 토큰을 스캔하여 반환
   588→func (l *Lexer) ScanAll() []Token {
   589→	var tokens []Token
   590→	for {
   591→		token := l.NextToken()
   592→		tokens = append(tokens, token)
   593→		if token.Type == TokenEOF {
   594→			break
   595→		}
   596→	}
   597→	return tokens
   598→}
   599→

