   657→// parseForStmt - for 루프 파싱
   658→func (p *Parser) parseForStmt() ast.Stmt {
   659→	forToken := p.current
   660→	p.advance()
   661→
   662→	if p.current.Type != lexer.TokenIdentifier {
   663→		p.error("for 루프 변수가 필요합니다")
   664→		return nil
   665→	}
   666→	loopVar := p.current.Lexeme
   667→	p.advance()
   668→
   669→	if !p.match(lexer.TokenKeywordIn) {
   670→		p.error("for 루프에서 'in'이 필요합니다")
   671→		return nil
   672→	}
   673→
   674→	iterator := p.parseExpression()
   675→	if iterator == nil {
   676→		p.error("반복 대상이 필요합니다")
   677→		return nil
   678→	}
   679→
   680→	body := p.parseBlock(lexer.TokenKeywordEnd)
   681→	p.expect(lexer.TokenKeywordEnd)
   682→
   683→	return &ast.ForStmt{
   684→		Variable: loopVar,
   685→		Iterator: iterator,
   686→		Body:     body,
   687→		For:      forToken,
   688→	}
   689→}
   690→
   691→// parseReturnStmt - return 문 파싱
   692→func (p *Parser) parseReturnStmt() ast.Stmt {
   693→	retToken := p.current
   694→	p.advance()
   695→
   696→	var value ast.Expr
   697→	if p.current.Type != lexer.TokenNewline && p.current.Type != lexer.TokenEOF {
   698→		value = p.parseExpression()
   699→	}
   700→
   701→	return &ast.ReturnStmt{
   702→		Value:  value,
   703→		Return: retToken,
   704→	}
   705→}
   706→
   707→// parseBlock - 코드 블록 파싱
   708→func (p *Parser) parseBlock(endTokens ...lexer.TokenType) []ast.Stmt {
   709→	stmts := []ast.Stmt{}
   710→
   711→	for {
   712→		if p.isIn(p.current.Type, endTokens...) || p.current.Type == lexer.TokenEOF {
   713→			break
   714→		}
   715→
   716→		if p.match(lexer.TokenNewline) {
   717→			continue
   718→		}
   719→
   720→		stmt := p.parseStatement()
   721→		if stmt != nil {
   722→			stmts = append(stmts, stmt)
   723→		}
   724→
   725→		for p.match(lexer.TokenNewline, lexer.TokenSemicolon) {
   726→		}
   727→	}
   728→
   729→	return stmts
   730→}
   731→
   732→// parseTryStmt - try-catch 문 파싱
   733→func (p *Parser) parseTryStmt() ast.Stmt {
   734→	tryToken := p.current
   735→	p.advance()
   736→
   737→	tryBody := p.parseBlock(lexer.TokenKeywordCatch, lexer.TokenKeywordFinally, lexer.TokenKeywordEnd)
   738→
   739→	catches := []*ast.CatchClause{}
   740→	for p.match(lexer.TokenKeywordCatch) {
   741→		catchToken := p.tokens[p.pos-1]
   742→		catchBody := p.parseBlock(lexer.TokenKeywordCatch, lexer.TokenKeywordFinally, lexer.TokenKeywordEnd)
   743→		catches = append(catches, &ast.CatchClause{
   744→			Body:  catchBody,
   745→			Catch: catchToken,
   746→		})
   747→	}
   748→
   749→	var finallyBody []ast.Stmt
   750→	if p.match(lexer.TokenKeywordFinally) {
   751→		finallyBody = p.parseBlock(lexer.TokenKeywordEnd)
   752→	}
   753→
   754→	p.expect(lexer.TokenKeywordEnd)
   755→
   756→	return &ast.TryStmt{
   757→		Try:     tryBody,
   758→		Catches: catches,
   759→		Finally: finallyBody,
   760→		Try_:    tryToken,
   761→	}
   762→}
   763→
   764→// parseConstDecl - const 선언 파싱
   765→func (p *Parser) parseConstDecl() ast.Stmt {
   766→	constToken := p.current
