   790→// parseLetStmt - let 선언 파싱
   791→func (p *Parser) parseLetStmt() ast.Stmt {
   792→	letToken := p.current
   793→	p.advance()
   794→
   795→	if p.current.Type != lexer.TokenIdentifier {
   796→		p.error("변수 이름이 필요합니다")
   797→		return nil
   798→	}
   799→	name := p.current.Lexeme
   800→	p.advance()
   801→
   802→	p.expect(lexer.TokenEqual)
   803→	value := p.parseExpression()
   804→	if value == nil {
