   819→
   820→// buildPrecedenceMap - 연산자 우선순위 맵 구축
   821→func buildPrecedenceMap() map[lexer.TokenType]int {
   822→	return map[lexer.TokenType]int{
   823→		lexer.TokenOr:            1,
   824→		lexer.TokenAnd:           2,
   825→		lexer.TokenEqualEqual:    3,
   826→		lexer.TokenNotEqual:      3,
   827→		lexer.TokenLess:          3,
   828→		lexer.TokenLessEqual:     3,
   829→		lexer.TokenGreater:       3,
   830→		lexer.TokenGreaterEqual:  3,
   831→		lexer.TokenPipe:          4,
   832→		lexer.TokenAmpersand:     5,
   833→		lexer.TokenLeftShift:     6,
   834→		lexer.TokenRightShift:    6,
   835→		lexer.TokenUnsignedRightShift: 6,
   836→		lexer.TokenPlus:          7,
   837→		lexer.TokenMinus:         7,
   838→		lexer.TokenStar:          8,
   839→		lexer.TokenSlash:         8,
   840→		lexer.TokenPercent:       8,
   841→		lexer.TokenCaret:         9,
   842→		lexer.TokenDoubleDot:     10,
   843→	}
   844→}
   845→
   846→// getPrecedence - 연산자의 우선순위 얻기
   847→func (p *Parser) getPrecedence(tokenType lexer.TokenType) int {
   848→	if prec, ok := p.precMap[tokenType]; ok {
   849→		return prec
   850→	}
   851→	return 0
   852→}
   853→
   854→// isBinaryOp - 이항 연산자인지 확인
   855→func (p *Parser) isBinaryOp(tokenType lexer.TokenType) bool {
   856→	return p.getPrecedence(tokenType) > 0
   857→}
   858→
   859→// isUnaryOp - 단항 연산자인지 확인
   860→func (p *Parser) isUnaryOp(tokenType lexer.TokenType) bool {
   861→	switch tokenType {
   862→	case lexer.TokenMinus, lexer.TokenNot, lexer.TokenTilde, lexer.TokenPlus:
   863→		return true
   864→	}
   865→	return false
   866→}
   867→
   868→// isLeftAssociative - 좌결합 연산자인지 확인
   869→func (p *Parser) isLeftAssociative(tokenType lexer.TokenType) bool {
   870→	// 대부분의 연산자가 좌결합
   871→	// 우결합: power (^) 등
   872→	switch tokenType {
   873→	case lexer.TokenCaret:
   874→		return false // 우결합
   875→	}
   876→	return true
   877→}
   878→
   879→// isAssignmentOp - 할당 연산자인지 확인
   880→func (p *Parser) isAssignmentOp(tokenType lexer.TokenType) bool {
   881→	switch tokenType {
   882→	case lexer.TokenEqual, lexer.TokenPlusAssign, lexer.TokenMinusAssign,
   883→		lexer.TokenStarAssign, lexer.TokenSlashAssign, lexer.TokenPercentAssign,
   884→		lexer.TokenCaretAssign, lexer.TokenAndAssign, lexer.TokenPipeAssign:
   885→		return true
   886→	}
   887→	return false
   888→}
   889→
   890→// isIn - 주어진 토큰 타입이 목록에 있는지 확인
   891→func (p *Parser) isIn(tokenType lexer.TokenType, types ...lexer.TokenType) bool {
   892→	for _, t := range types {
   893→		if tokenType == t {
   894→			return true
   895→		}
   896→	}
   897→	return false
   898→}
   899→

